s='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Uniform rectangular fields at least 5x5 are the marked regions.
    # Use a summed run intersection so each candidate rectangle is tested exactly.
    for r0 in range(h):
        for c0 in range(w):
            color = grid[r0][c0]
            width = w - c0
            for r1 in range(r0, h):
                run = 0
                while c0 + run < w and grid[r1][c0 + run] == color:
                    run += 1
                width = min(width, run)
                if r1 - r0 + 1 >= 5 and width >= 5:
                    for r in range(r0, r1 + 1):
                        for c in range(c0, c0 + width):
                            out[r][c] = 4
    return out
'''
